svg.script:
(function () {
  var CELL = 20, COLS = 25, ROWS = 25;
  var snakeG = document.getElementById('snake');
  var foodG = document.getElementById('food');
  var scoreT = document.getElementById('score');
  var overlay = document.getElementById('overlay');
  var snake, dir, nextDir, food, score, running, gameOver, timer;

  function init() {
    snake = [{x:12,y:12},{x:11,y:12},{x:10,y:12}];
    dir = {x:1,y:0}; nextDir = {x:1,y:0};
    score = 0; running = false; gameOver = false;
    if (timer) { clearInterval(timer); timer = null; }
    placeFood();
    draw();
    scoreT.textContent = 'Score: 0';
    overlay.textContent = 'Press any arrow key to start';
    overlay.setAttribute('fill', '#f4f4f5');
  }

  function placeFood() {
    do {
      food = {x: Math.floor(Math.random()*COLS), y: Math.floor(Math.random()*ROWS)};
    } while (snake.some(function (s) { return s.x === food.x && s.y === food.y; }));
  }

  function draw() {
    while (snakeG.firstChild) snakeG.removeChild(snakeG.firstChild);
    while (foodG.firstChild) foodG.removeChild(foodG.firstChild);
    for (var i = 0; i < snake.length; i++) {
      var r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      r.setAttribute('x', snake[i].x*CELL + 1);
      r.setAttribute('y', snake[i].y*CELL + 1);
      r.setAttribute('width', CELL - 2);
      r.setAttribute('height', CELL - 2);
      r.setAttribute('rx', 3);
      r.setAttribute('fill', i === 0 ? '#00ff9c' : '#0f6b4a');
      snakeG.appendChild(r);
    }
    var f = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    f.setAttribute('x', food.x*CELL + 1);
    f.setAttribute('y', food.y*CELL + 1);
    f.setAttribute('width', CELL - 2);
    f.setAttribute('height', CELL - 2);
    f.setAttribute('rx', 3);
    f.setAttribute('fill', '#ff4b4b');
    foodG.appendChild(f);
  }

  function step() {
    dir = nextDir;
    var head = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};
    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) { endGame(); return; }
    for (var i = 0; i < snake.length; i++) {
      if (snake[i].x === head.x && snake[i].y === head.y) { endGame(); return; }
    }
    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreT.textContent = 'Score: ' + score;
      placeFood();
    } else {
      snake.pop();
    }
    draw();
  }

  function endGame() {
    running = false; gameOver = true;
    if (timer) { clearInterval(timer); timer = null; }
    overlay.textContent = 'Game over — Score: ' + score + '. Press R to restart';
    overlay.setAttribute('fill', '#ff4b4b');
  }

  document.addEventListener('keydown', function (e) {
    var k = e.key;
    if (k === 'ArrowUp' || k === 'w' || k === 'W') { if (dir.y !== 1) nextDir = {x:0,y:-1}; e.preventDefault(); }
    else if (k === 'ArrowDown' || k === 's' || k === 'S') { if (dir.y !== -1) nextDir = {x:0,y:1}; e.preventDefault(); }
    else if (k === 'ArrowLeft' || k === 'a' || k === 'A') { if (dir.x !== 1) nextDir = {x:-1,y:0}; e.preventDefault(); }
    else if (k === 'ArrowRight' || k === 'd' || k === 'D') { if (dir.x !== -1) nextDir = {x:1,y:0}; e.preventDefault(); }
    else if (k === 'r' || k === 'R') { init(); return; }
    if (!running && !gameOver) {
      running = true;
      overlay.textContent = '';
      timer = setInterval(step, 120);
    }
  });

  init();
})();
